import openpyxl, datetime
from collections import Counter
wb = openpyxl.load_workbook('task/init.xlsx')
src = wb['Imported Data']
dst = wb['Duplicates']

def todate(d):
    if isinstance(d, datetime.datetime): return d
    return datetime.datetime.strptime(d,'%d/%m/%Y')

rows=[]
for r in range(2,12):
    c=src.cell(r,3).value
    if c:
        rows.append((r,[src.cell(r,col).value for col in range(1,6)]))

cnt=Counter(v[2] for r,v in rows)
dups={}
for r,v in rows:
    if cnt[v[2]]>1:
        sk=(v[4],todate(v[3]))
        if v[2] not in dups or sk<dups[v[2]][0]:
            dups[v[2]]=(sk,(r,v))

sel=[dups[k][1] for k in dups]
sel.sort(key=lambda x:(x[1][4],todate(x[1][3])))

for rr in range(1,6):
    for cc in range(1,6):
        dst.cell(rr,cc).value=None
        dst.cell(rr,cc).alignment=openpyxl.styles.Alignment()
for cc in range(1,6):
    dst.cell(1,cc).value=src.cell(1,cc).value

for i,(r,v) in enumerate(sel,start=2):
    for cc,val in enumerate(v,start=1):
        dc=dst.cell(i,cc)
        dc.value=val
        if cc==4:
            dc.alignment=openpyxl.styles.Alignment(horizontal='right')
            dc.number_format='mm-dd-yy'
wb.save('task/output.xlsx')
print('rows:',[x[0] for x in sel])
EOF
python3 task/solve.py
